class Solution:
    def longestString(self, x: int, y: int, z: int) -> int:
        pairs = min(x, y)
        extra = 1 if x != y else 0
        return (2 * pairs + extra + z) * 2

class Solution {
public:
    int longestString(int x, int y, int z) {
        int pairs = min(x, y);
        int extra = (x != y) ? 1 : 0;
        return (2 * pairs + extra + z) * 2;
    }
};

